def flatten(d, prefix=""):
    for k, v in d.items():
        key = f"{prefix}.{k}" if prefix else k
        if isinstance(v, dict) and set(v.keys()) == {"en", "ar"} and all(isinstance(x, str) for x in v.values()):
            yield key, v
        else:
            yield from flatten(v, key)


def tree(lang):
    def walk(d):
        out = {}
        for k, v in d.items():
            if isinstance(v, dict) and set(v.keys()) == {"en", "ar"} and all(isinstance(x, str) for x in v.values()):
                out[k] = v[lang]
            else:
                out[k] = walk(v)
        return out
    return walk(S)
